package glitch

import data.glitch_lib

# Helper to check if expression derives from external input (variable reference or function call)
is_external_input(expr) {
    expr.ir_type == "VariableReference"
}

is_external_input(expr) {
    expr.ir_type == "FunctionCall"
}

is_external_input(expr) {
    expr.ir_type == "MethodCall"
}

is_external_input(expr) {
    expr.ir_type == "Access"
    is_external_input(expr.left)
}

# Helper to check if a conditional statement lacks a default/else branch
has_no_default_branch(cond) {
    cond.else_statement == null
}

has_no_default_branch(cond) {
    cond.else_statement != null
    not cond.else_statement.is_default
    cond.else_statement.type == "IF"
    has_no_default_branch(cond.else_statement)
}

# Helper to count discrete branches in a conditional chain
count_branches(cond) = n {
    count_branches_helper(cond, 0, n)
}

count_branches_helper(cond, acc, n) {
    cond.else_statement == null
    n := acc + 1
}

count_branches_helper(cond, acc, n) {
    cond.else_statement != null
    cond.else_statement.type == "IF"
    count_branches_helper(cond.else_statement, acc + 1, n)
}

count_branches_helper(cond, acc, n) {
    cond.else_statement != null
    cond.else_statement.is_default
    n := acc + 2
}

# Check if conditional performs security-relevant actions
is_security_relevant(node) {
    walk(node, [_, n])
    n.ir_type == "AtomicUnit"
}

is_security_relevant(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    attr_names := {"user", "group", "owner", "permissions", "acl", "policy", "encryption", "tls", "ssl", "cipher", "auth", "authentication", "access", "firewall", "security_group", "ingress", "egress"}
    n.name == attr_names[_]
}

is_security_relevant(node) {
    walk(node, [_, n])
    n.ir_type == "Assign"
    walk(n, [_, an])
    an.ir_type == "Attribute"
    attr_names := {"user", "group", "owner", "permissions", "acl", "policy", "encryption", "tls", "ssl", "cipher", "auth", "authentication", "access", "firewall", "security_group", "ingress", "egress"}
    an.name == attr_names[_]
}

# Detect missing default in switch-style conditionals with external input selector
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, cond])
    cond.ir_type == "ConditionalStatement"
    cond.type == "SWITCH"

    # Has 3+ branches
    num_branches := count_branches(cond)
    num_branches >= 3

    # No default branch
    has_no_default_branch(cond)

    # Selector derives from external input
    is_external_input(cond.condition)

    # Security-relevant actions in branches
    is_security_relevant(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in switch statement with external input selector - Unhandled cases may lead to undefined behavior and security misconfigurations. (CWE-478)"
    }
}

# Detect missing default in multi-branch if-elif chains with external input selector
Glitch_Analysis[result] {
